-- +goose Up
-- Everyday voice catalog: 8 topics, 6 reusable peer personas, 15 Tier-S
-- scenarios (A1–B1). Personas are interlocutor archetypes shared across
-- scenarios, not one-per-scenario executives. Difficulty budgets follow the
-- CEFR scaling table: A1 4–6 turns with hint phrases, A2 6–10 turns with one
-- surprise follow-up, B1 8–14 turns (narrate + explain + say what you want).
INSERT INTO scenario_topics (id, slug, name, short_name, position) VALUES
 ('7a000001-0000-4000-8000-000000000001','food-drink','Food & Drink','Food & drink',1),
 ('7a000002-0000-4000-8000-000000000002','shopping','Shopping & Markets','Shopping',2),
 ('7a000003-0000-4000-8000-000000000003','getting-around','Getting Around Town','Getting around',3),
 ('7a000004-0000-4000-8000-000000000004','travel','Travel & Hotels','Travel',4),
 ('7a000005-0000-4000-8000-000000000005','home-daily-life','Home & Daily Life','Daily life',5),
 ('7a000006-0000-4000-8000-000000000006','health','Health & Pharmacy','Health',6),
 ('7a000007-0000-4000-8000-000000000007','social-small-talk','Social & Small Talk','Small talk',7),
 ('7a000008-0000-4000-8000-000000000008','services-money','Services & Money','Services',8)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO personas (id, name, role_title, personality, style, objective, gender, default_cefr) VALUES
 ('7b000001-0000-4000-8000-000000000001','Maya','Barista','Warm, cheerful','Takes café orders, small-talks regulars','Take the order right and keep it friendly','female','A1'),
 ('7b000002-0000-4000-8000-000000000002','Sam','Shop assistant','Helpful, patient','Helps customers at any counter, handles returns kindly','Solve the customer''s problem without rushing','male','A1'),
 ('7b000003-0000-4000-8000-000000000003','Rosa','Taxi driver','Chatty local','Gives directions and town tips, one question at a time','Get the passenger where they need to go','female','A1'),
 ('7b000004-0000-4000-8000-000000000004','Daniel','Hotel receptionist','Polite, clear','Checks guests in, explains the basics slowly','Check the guest in with zero confusion','male','A2'),
 ('7b000005-0000-4000-8000-000000000005','Lin','Pharmacist','Kind, careful','Explains dosage simply, double-checks understanding','Make sure the patient knows what to do','female','A2'),
 ('7b000006-0000-4000-8000-000000000006','Alex','New friend','Easygoing peer','Chats hobbies and weekend plans like a friend','Keep the chat going and make plans','male','B1')
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, topic_id, persona_id, title, objective, cefr_level, max_duration, details) VALUES
 ('7c000001-0000-4000-8000-000000000001','7a000001-0000-4000-8000-000000000001','7b000001-0000-4000-8000-000000000001','Ordering coffee to go','Order a drink, answer size and extras questions, and ask for the bill.','A1',5,$json$ {"context": ["You are at Maya's café counter. She is warm and speaks clearly.", "Order one drink to go. She will ask about size and extras — one question at a time."], "opening": {"label": "Maya (smiling):", "text": "Hi there! What can I get for you today?"}, "role": "Customer", "goal_format": "4–6 turns · hints: I'd like…, To go, please, How much is it?", "interlocutor_role": "Barista", "vocab": ["to go", "size", "extra", "bill"]} $json$),
 ('7c000002-0000-4000-8000-000000000002','7a000007-0000-4000-8000-000000000007','7b000006-0000-4000-8000-000000000006','Meeting a new classmate','Greet, introduce yourself, say where you are from, and say goodbye warmly.','A1',5,$json$ {"context": ["Alex just joined your class and sits next to you. He is easygoing and curious.", "Say hello, share your name and where you are from, ask one question back."], "opening": {"label": "Alex:", "text": "Hey! I just moved here. What's your name?"}, "role": "New classmate", "goal_format": "4–6 turns · hints: My name is…, I'm from…, Nice to meet you", "interlocutor_role": "Peer friend", "vocab": ["greet", "introduce", "from", "goodbye"]} $json$),
 ('7c000003-0000-4000-8000-000000000003','7a000003-0000-4000-8000-000000000003','7b000003-0000-4000-8000-000000000003','Asking for street directions','Ask where a place is, follow the directions, and confirm you understood.','A1',5,$json$ {"context": ["You are lost near the station. Rosa the taxi driver knows every street.", "Ask how to get to the city library. Repeat the key turn back to confirm."], "opening": {"label": "Rosa:", "text": "You look a bit lost! Where are you trying to get to?"}, "role": "Lost pedestrian", "goal_format": "4–6 turns · hints: Where is…?, Go straight, Turn left/right, Thank you", "interlocutor_role": "Helpful local", "vocab": ["straight", "turn", "corner", "near"]} $json$),
 ('7c000004-0000-4000-8000-000000000004','7a000002-0000-4000-8000-000000000002','7b000002-0000-4000-8000-000000000002','Morning grocery run','Find three items, ask prices, and pay by card.','A1',5,$json$ {"context": ["Sam is stocking shelves and happy to help. You need milk, bread, and apples.", "Ask where things are and what they cost, then pay by card."], "opening": {"label": "Sam:", "text": "Morning! Looking for anything in particular?"}, "role": "Shopper", "goal_format": "4–6 turns · hints: Where is…?, How much…?, By card, please", "interlocutor_role": "Store clerk", "vocab": ["price", "aisle", "change", "receipt"]} $json$),
 ('7c000005-0000-4000-8000-000000000005','7a000003-0000-4000-8000-000000000003','7b000003-0000-4000-8000-000000000003','Taxi to the station','Give the destination, confirm the route and price, and thank the driver.','A1',6,$json$ {"context": ["Rosa's taxi just pulled up. Your train leaves in 25 minutes.", "Say where you are going, agree on the price, and chat a little on the way."], "opening": {"label": "Rosa:", "text": "Hop in! Where to?"}, "role": "Passenger", "goal_format": "4–6 turns · hints: To the station, please, How much…?, Keep the change", "interlocutor_role": "Taxi driver", "vocab": ["destination", "fare", "hurry", "stop"]} $json$),
 ('7c000006-0000-4000-8000-000000000006','7a000004-0000-4000-8000-000000000004','7b000004-0000-4000-8000-000000000004','Buying a train ticket','Ask about times and prices, then buy a single or return ticket.','A1',6,$json$ {"context": ["Daniel is covering the station ticket desk today. You want the 9:40 to the city.", "Ask when it leaves, what it costs, and buy your ticket."], "opening": {"label": "Daniel:", "text": "Good morning! Where are you travelling today?"}, "role": "Traveler", "goal_format": "4–6 turns · hints: Single or return?, What time…?, A ticket to…, please", "interlocutor_role": "Ticket agent", "vocab": ["single", "return", "platform", "depart"]} $json$),
 ('7c000007-0000-4000-8000-000000000007','7a000007-0000-4000-8000-000000000007','7b000006-0000-4000-8000-000000000006','Weekend small talk','Open a two-minute chat about weather, the weekend, and plans.','A2',6,$json$ {"context": ["Alex messages on Monday morning. Keep a friendly chat going past hello.", "Cover the weather, your weekend, and one plan for next weekend."], "opening": {"label": "Alex:", "text": "Morning! How was your weekend?"}, "role": "Friend", "goal_format": "6–10 turns · one surprise follow-up ok · hints: It was great, How about you?, I'm going to…", "interlocutor_role": "Peer friend", "vocab": ["weekend", "weather", "plan", "sounds fun"]} $json$),
 ('7c000008-0000-4000-8000-000000000008','7a000001-0000-4000-8000-000000000001','7b000001-0000-4000-8000-000000000001','Wrong coffee order','Flag a wrong drink politely and get the right one.','A2',6,$json$ {"context": ["Maya handed you someone else's drink: you ordered oat milk, this is whole milk.", "Point it out kindly — she wants to fix it, not argue."], "opening": {"label": "Maya:", "text": "Here's your latte! Enjoy!"}, "role": "Customer", "goal_format": "6–10 turns · one surprise follow-up ok · hints: Sorry, I ordered…, Could I get…?, No worries", "interlocutor_role": "Barista", "vocab": ["mistake", "replace", "patient", "apologize"]} $json$),
 ('7c000009-0000-4000-8000-000000000009','7a000004-0000-4000-8000-000000000004','7b000004-0000-4000-8000-000000000004','Hotel check-in','Check in with a booking, ask about Wi-Fi, breakfast, and checkout time.','A2',8,$json$ {"context": ["You booked two nights under the name Rivera. Daniel is on reception.", "Check in, then ask the three things every traveler asks: Wi-Fi, breakfast, checkout."], "opening": {"label": "Daniel:", "text": "Welcome! Do you have a reservation with us?"}, "role": "Guest", "goal_format": "6–10 turns · one surprise follow-up ok · hints: Under the name…, Is breakfast included?, What time is checkout?", "interlocutor_role": "Receptionist", "vocab": ["reservation", "included", "checkout", "password"]} $json$),
 ('7c000010-0000-4000-8000-000000000010','7a000004-0000-4000-8000-000000000004','7b000004-0000-4000-8000-000000000004','Airport check-in question','Check in bags, show ID, and answer the security questions.','A2',8,$json$ {"context": ["Daniel is on the airline desk. Your bag is slightly overweight.", "Check in, show your ID, and handle the overweight-bag surprise calmly."], "opening": {"label": "Daniel:", "text": "Hello! Passport and ticket, please. One bag to check in?"}, "role": "Passenger", "goal_format": "6–10 turns · one surprise follow-up ok · hints: Here you are, How much extra…?, Gate number?", "interlocutor_role": "Airline agent", "vocab": ["overweight", "fee", "gate", "boarding"]} $json$),
 ('7c000011-0000-4000-8000-000000000011','7a000006-0000-4000-8000-000000000006','7b000005-0000-4000-8000-000000000005','Booking a clinic visit','Book or move an appointment by phone: spell your name and confirm.','A2',7,$json$ {"context": ["Lin answers the clinic phone. You need a Thursday morning slot for a sore throat.", "Book the slot, spell your surname, and repeat the time back."], "opening": {"label": "Lin:", "text": "Good afternoon, Riverside Clinic. How can I help?"}, "role": "Caller", "goal_format": "6–10 turns · one surprise follow-up ok · hints: I'd like to book…, Could you spell that…?, See you then", "interlocutor_role": "Receptionist", "vocab": ["appointment", "spell", "confirm", "symptom"]} $json$),
 ('7c000012-0000-4000-8000-000000000012','7a000006-0000-4000-8000-000000000006','7b000005-0000-4000-8000-000000000005','Picking up medicine','Pick up a prescription and ask about dosage and side effects.','A2',7,$json$ {"context": ["Your prescription is ready. Lin wants to be sure you know how to take it.", "Ask how many pills, when, and what to watch out for."], "opening": {"label": "Lin:", "text": "Hi! Picking something up today?"}, "role": "Patient", "goal_format": "6–10 turns · one surprise follow-up ok · hints: How often…?, Side effects?, Thank you", "interlocutor_role": "Pharmacist", "vocab": ["dosage", "twice a day", "side effect", "prescription"]} $json$),
 ('7c000013-0000-4000-8000-000000000013','7a000002-0000-4000-8000-000000000002','7b000002-0000-4000-8000-000000000002','Trying on jeans','Ask for a size, try them on, and decide.','A2',8,$json$ {"context": ["You like the jeans but 32 is too tight. Sam knows where everything lives.", "Ask for a 34, use the fitting room, then buy or politely pass."], "opening": {"label": "Sam:", "text": "Those look great on the hanger! Want to try them on?"}, "role": "Shopper", "goal_format": "6–10 turns · one surprise follow-up ok · hints: Too tight/loose, Fitting room?, I'll take them", "interlocutor_role": "Shop assistant", "vocab": ["size", "try on", "fitting room", "tight"]} $json$),
 ('7c000014-0000-4000-8000-000000000014','7a000008-0000-4000-8000-000000000008','7b000002-0000-4000-8000-000000000002','Sending a parcel','Send a parcel abroad: fill the form, ask the price, get tracking.','A2',7,$json$ {"context": ["Sam is covering the post counter. Your parcel goes abroad and needs a customs form.", "Declare the contents, ask the price and delivery time, get the tracking number."], "opening": {"label": "Sam:", "text": "Hi there! Sending something today?"}, "role": "Sender", "goal_format": "6–10 turns · one surprise follow-up ok · hints: How much to…?, How long…?, Tracking number?", "interlocutor_role": "Postal clerk", "vocab": ["parcel", "customs", "tracking", "postage"]} $json$),
 ('7c000015-0000-4000-8000-000000000015','7a000002-0000-4000-8000-000000000002','7b000002-0000-4000-8000-000000000002','Returning a faulty kettle','Explain what broke, ask for a refund or exchange, and stay friendly.','B1',8,$json$ {"context": ["The kettle you bought yesterday won't switch off. You have the receipt.", "Narrate what happened, explain what you want, and respond to one pushback (repair vs refund)."], "opening": {"label": "Sam:", "text": "Hi! What can I do for you today?"}, "role": "Customer", "goal_format": "8–14 turns · narrate + explain + say what you want · hints: It won't…, I'd like a refund…, That works if…", "interlocutor_role": "Store clerk", "vocab": ["faulty", "refund", "exchange", "receipt"]} $json$),
 ('7c000016-0000-4000-8000-000000000016','7a000005-0000-4000-8000-000000000005','7b000006-0000-4000-8000-000000000006','Talking about your morning routine','Say what time you get up, what you eat, and how you get to work or school.','A1',5,$json$ {"context": ["Alex is curious how your mornings look. He gets up at 6:30 and always skips breakfast.", "Tell him your wake-up time, your breakfast, and how you get to work or school."], "opening": {"label": "Alex:", "text": "Be honest — what time do you actually get up?"}, "role": "Friend", "goal_format": "4–6 turns · hints: I get up at…, For breakfast…, I go by…", "interlocutor_role": "Peer friend", "vocab": ["get up", "breakfast", "commute", "alarm"]} $json$),
 ('7c000017-0000-4000-8000-000000000017','7a000005-0000-4000-8000-000000000005','7b000006-0000-4000-8000-000000000006','Planning a weekend together','Suggest two ideas, agree on one, and fix a time and place to meet.','A2',6,$json$ {"context": ["Alex wants to do something together this weekend — not just chat about it.", "Suggest two ideas, pick one together, and fix when and where to meet. He will throw in one rainy-day twist."], "opening": {"label": "Alex:", "text": "Weekend is coming! Got any plans yet?"}, "role": "Friend", "goal_format": "6–10 turns · one surprise follow-up ok · hints: How about…?, Saturday works for me, Let's meet at…", "interlocutor_role": "Peer friend", "vocab": ["suggest", "agree", "meet up", "weekend"]} $json$),
 ('7c000018-0000-4000-8000-000000000018','7a000005-0000-4000-8000-000000000005','7b000002-0000-4000-8000-000000000002','Reporting a leak to your landlord','Describe the leak, explain why it is urgent, and agree on a repair day.','B1',8,$json$ {"context": ["Water is dripping from your bathroom ceiling since last night. Sam manages the building and answers fast.", "Describe what is happening, explain why it cannot wait, and push back once if Friday is too late."], "opening": {"label": "Sam:", "text": "You sounded worried on the phone. What's going on?"}, "role": "Tenant", "goal_format": "8–14 turns · narrate + explain + say what you want · hints: Since last night…, It is getting worse…, Could someone come…?", "interlocutor_role": "Building manager", "vocab": ["leak", "drip", "urgent", "repair"]} $json$)
ON CONFLICT (id) DO NOTHING;

-- Curated preview order: ListTopicsWithPreview ranks each topic's scenarios
-- by created_at, and one INSERT stamps every row with the same transaction
-- timestamp, so give the rows distinct, increasing timestamps in the order
-- they are listed above (first listed = oldest).
UPDATE scenarios AS s
SET created_at = now() - make_interval(mins => o.pos)
FROM (VALUES
    ('7c000001-0000-4000-8000-000000000001', 15),
    ('7c000002-0000-4000-8000-000000000002', 14),
    ('7c000003-0000-4000-8000-000000000003', 13),
    ('7c000004-0000-4000-8000-000000000004', 12),
    ('7c000005-0000-4000-8000-000000000005', 11),
    ('7c000006-0000-4000-8000-000000000006', 10),
    ('7c000007-0000-4000-8000-000000000007', 9),
    ('7c000008-0000-4000-8000-000000000008', 8),
    ('7c000009-0000-4000-8000-000000000009', 7),
    ('7c000010-0000-4000-8000-000000000010', 6),
    ('7c000011-0000-4000-8000-000000000011', 5),
    ('7c000012-0000-4000-8000-000000000012', 4),
    ('7c000013-0000-4000-8000-000000000013', 3),
    ('7c000014-0000-4000-8000-000000000014', 2),
    ('7c000015-0000-4000-8000-000000000015', 1),
    ('7c000016-0000-4000-8000-000000000016', 3),
    ('7c000017-0000-4000-8000-000000000017', 2),
    ('7c000018-0000-4000-8000-000000000018', 1)
) AS o(id, pos)
WHERE s.id = o.id::uuid;

